class Allocator {
    private final int[] memory;

    public Allocator(int n) {
        memory = new int[n];
    }

    public int allocate(int size, int mID) {
        int run = 0;
        for (int i = 0; i < memory.length; i++) {
            if (memory[i] == 0) {
                run++;
            } else {
                run = 0;
            }
            if (run == size) {
                int start = i - size + 1;
                for (int j = start; j <= i; j++) {
                    memory[j] = mID;
                }
                return start;
            }
        }
        return -1;
    }

    public int free(int mID) {
        int freed = 0;
        for (int i = 0; i < memory.length; i++) {
            if (memory[i] == mID) {
                memory[i] = 0;
                freed++;
            }
        }
        return freed;
    }
}

import java.util.Arrays;
import java.util.BitSet;

class Allocator {
    private final int n;
    private final BitSet used;
    private final int[] owner;

    public Allocator(int n) {
        this.n = n;
        used = new BitSet(n);
        owner = new int[n];
    }

    public int allocate(int size, int mID) {
        int start = used.nextClearBit(0);
        while (start < n) {
            int nextUsed = used.nextSetBit(start);
            int end = nextUsed == -1 ? n : nextUsed;
            if (end - start >= size) {
                used.set(start, start + size);
                Arrays.fill(owner, start, start + size, mID);
                return start;
            }
            if (nextUsed == -1) {
                return -1;
            }
            start = used.nextClearBit(nextUsed + 1);
        }
        return -1;
    }

    public int free(int mID) {
        int freed = 0;
        for (int i = 0; i < n; i++) {
            if (owner[i] == mID) {
                owner[i] = 0;
                used.clear(i);
                freed++;
            }
        }
        return freed;
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

class Allocator {
    private static class Block {
        int end;
        int mID;
        Block(int end, int mID) {
            this.end = end;
            this.mID = mID;
        }
    }

    private final int n;
    private final TreeMap<Integer, Block> allocatedByStart = new TreeMap<>();
    private final Map<Integer, List<Integer>> startsById = new HashMap<>();

    public Allocator(int n) {
        this.n = n;
    }

    public int allocate(int size, int mID) {
        int previousEnd = 0;
        for (Map.Entry<Integer, Block> entry : allocatedByStart.entrySet()) {
            int start = entry.getKey();
            if (start - previousEnd >= size) {
                addBlock(previousEnd, previousEnd + size, mID);
                return previousEnd;
            }
            previousEnd = entry.getValue().end;
        }
        if (n - previousEnd >= size) {
            addBlock(previousEnd, previousEnd + size, mID);
            return previousEnd;
        }
        return -1;
    }

    public int free(int mID) {
        List<Integer> starts = startsById.remove(mID);
        if (starts == null) {
            return 0;
        }
        int freed = 0;
        for (int start : starts) {
            Block block = allocatedByStart.remove(start);
            if (block != null) {
                freed += block.end - start;
            }
        }
        return freed;
    }

    private void addBlock(int start, int end, int mID) {
        allocatedByStart.put(start, new Block(end, mID));
        startsById.computeIfAbsent(mID, unused -> new ArrayList<>()).add(start);
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

class Allocator {
    private final TreeMap<Integer, Integer> freeByStart = new TreeMap<>();
    private final Map<Integer, List<int[]>> rangesById = new HashMap<>();

    public Allocator(int n) {
        freeByStart.put(0, n);
    }

    public int allocate(int size, int mID) {
        Map.Entry<Integer, Integer> chosen = null;
        for (Map.Entry<Integer, Integer> entry : freeByStart.entrySet()) {
            if (entry.getValue() - entry.getKey() >= size) {
                chosen = entry;
                break;
            }
        }
        if (chosen == null) {
            return -1;
        }
        int start = chosen.getKey();
        int end = chosen.getValue();
        freeByStart.remove(start);
        if (start + size < end) {
            freeByStart.put(start + size, end);
        }
        rangesById.computeIfAbsent(mID, unused -> new ArrayList<>()).add(new int[]{start, start + size});
        return start;
    }

    public int free(int mID) {
        List<int[]> ranges = rangesById.remove(mID);
        if (ranges == null) {
            return 0;
        }
        int freed = 0;
        for (int[] range : ranges) {
            freed += range[1] - range[0];
            addFreeRange(range[0], range[1]);
        }
        return freed;
    }

    private void addFreeRange(int start, int end) {
        Map.Entry<Integer, Integer> lower = freeByStart.floorEntry(start);
        if (lower != null && lower.getValue() >= start) {
            start = lower.getKey();
            end = Math.max(end, lower.getValue());
            freeByStart.remove(lower.getKey());
        }
        Map.Entry<Integer, Integer> higher = freeByStart.ceilingEntry(start);
        while (higher != null && higher.getKey() <= end) {
            end = Math.max(end, higher.getValue());
            freeByStart.remove(higher.getKey());
            higher = freeByStart.ceilingEntry(start);
        }
        freeByStart.put(start, end);
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Allocator {
    private final int n;
    private final int[] prefix;
    private final int[] suffix;
    private final int[] best;
    private final int[] length;
    private final int[] lazy;
    private final Map<Integer, List<int[]>> rangesById = new HashMap<>();

    public Allocator(int n) {
        this.n = n;
        int size = n * 4 + 5;
        prefix = new int[size];
        suffix = new int[size];
        best = new int[size];
        length = new int[size];
        lazy = new int[size];
        build(1, 0, n - 1);
    }

    public int allocate(int size, int mID) {
        if (best[1] < size) {
            return -1;
        }
        int start = firstFit(1, 0, n - 1, size);
        update(1, 0, n - 1, start, start + size - 1, 1);
        rangesById.computeIfAbsent(mID, unused -> new ArrayList<>()).add(new int[]{start, start + size - 1});
        return start;
    }

    public int free(int mID) {
        List<int[]> ranges = rangesById.remove(mID);
        if (ranges == null) {
            return 0;
        }
        int freed = 0;
        for (int[] range : ranges) {
            freed += range[1] - range[0] + 1;
            update(1, 0, n - 1, range[0], range[1], 0);
        }
        return freed;
    }

    private void build(int node, int left, int right) {
        length[node] = right - left + 1;
        lazy[node] = 0;
        prefix[node] = suffix[node] = best[node] = length[node];
        if (left == right) {
            return;
        }
        int mid = left + (right - left) / 2;
        build(node * 2, left, mid);
        build(node * 2 + 1, mid + 1, right);
    }

    private int firstFit(int node, int left, int right, int size) {
        if (left == right) {
            return left;
        }
        push(node);
        int mid = left + (right - left) / 2;
        int child = node * 2;
        if (best[child] >= size) {
            return firstFit(child, left, mid, size);
        }
        if (suffix[child] + prefix[child + 1] >= size) {
            return mid - suffix[child] + 1;
        }
        return firstFit(child + 1, mid + 1, right, size);
    }

    private void update(int node, int left, int right, int ql, int qr, int value) {
        if (ql <= left && right <= qr) {
            apply(node, value);
            return;
        }
        push(node);
        int mid = left + (right - left) / 2;
        if (ql <= mid) {
            update(node * 2, left, mid, ql, qr, value);
        }
        if (qr > mid) {
            update(node * 2 + 1, mid + 1, right, ql, qr, value);
        }
        pull(node);
    }

    private void apply(int node, int value) {
        if (value == 0) {
            prefix[node] = suffix[node] = best[node] = length[node];
        } else {
            prefix[node] = suffix[node] = best[node] = 0;
        }
        lazy[node] = value;
    }

    private void push(int node) {
        if (lazy[node] == -1) {
            return;
        }
        apply(node * 2, lazy[node]);
        apply(node * 2 + 1, lazy[node]);
        lazy[node] = -1;
    }

    private void pull(int node) {
        int left = node * 2;
        int right = left + 1;
        prefix[node] = prefix[left] == length[left] ? length[left] + prefix[right] : prefix[left];
        suffix[node] = suffix[right] == length[right] ? length[right] + suffix[left] : suffix[right];
        best[node] = Math.max(Math.max(best[left], best[right]), suffix[left] + prefix[right]);
        lazy[node] = -1;
    }
}
